    """Restore 2-masked cells from the square pattern's dihedral symmetries."""
    n = len(grid)
    if any(len(row) != n for row in grid):
        raise ValueError("Expected a square grid")
    out = [row[:] for row in grid]
    for r in range(n):
        for c in range(n):
            if grid[r][c] == 2:
                # D4 orbit: transpose, reflections, and quarter turns.
                orbit = {
                    (r, c), (c, r),
                    (n - 1 - r, c), (r, n - 1 - c),
                    (n - 1 - r, n - 1 - c),
                    (c, n - 1 - r), (n - 1 - c, r),
                    (n - 1 - c, n - 1 - r),
                }
                known = [grid[rr][cc] for rr, cc in orbit if grid[rr][cc] != 2]
                if not known or any(v != known[0] for v in known):
